mapper.select:
SELECT c.id, c.school_id, s.school_name AS school_name, c.grade_id, g.grade_name AS grade_name, c.class_name AS name, c.class_code AS code, c.sort AS class_num, c.head_teacher_id, t.teacher_name AS head_teacher_name, c.status, c.sort, '' AS remark, c.create_time, (SELECT COUNT(1) FROM student st WHERE st.class_id = c.id AND st.deleted = 0) AS student_count FROM class_info c LEFT JOIN school s ON c.school_id = s.id LEFT JOIN grade g ON c.grade_id = g.id LEFT JOIN teacher t ON c.head_teacher_id = t.id WHERE c.deleted = 0
AND c.school_id = #{query.schoolId}
AND c.grade_id = #{query.gradeId}
AND c.class_name LIKE CONCAT('%', #{query.name}, '%')
AND c.head_teacher_id = #{query.headTeacherId}
AND c.status = #{query.status}
ORDER BY c.sort ASC, c.create_time DESC

SELECT id, school_id, grade_id, class_name AS name, class_code AS code, sort AS class_num, sort, '' AS remark FROM class_info WHERE grade_id = #{gradeId} AND deleted = 0
AND status = #{status}
ORDER BY sort ASC, create_time DESC

SELECT c.id, c.school_id, c.grade_id, c.class_name AS name, c.class_code AS code, c.sort AS class_num, c.sort, '' AS remark, g.grade_name AS grade_name FROM class_info c LEFT JOIN grade g ON c.grade_id = g.id WHERE c.school_id = #{schoolId} AND c.deleted = 0
AND c.status = #{status}
ORDER BY g.sort ASC, c.sort ASC
